# --- helper: parse 'The answer is X.' from a reply ---
import re
def parse_ans(rep):
    if not isinstance(rep,str): return None
    m=re.match(r'\s*The answer is (.*?)\.?\s*$', rep, re.S)
    return m.group(1).strip() if m else None

def gen_scores(path):
    out={}
    for ln in open(path):
