The saved teacher-forced runs `fwd_20`, `fwd_19`, `fwd_21`, etc. already contain the exact paired continuations I need. I will now compute, for each saved run, the summed log-probability of the guess reply versus the correct reply on the same wrong-guess prompts, plus the no-guess correct-reply log-probability. This reveals which saved candidate is least destructive and how far it moved the decision margin, without spending any forward passes.

```python
import os, json, numpy as np, glob, re
facts=[json.loads(l) for l in open('/practice/dev_facts.jsonl')]
q2f={f['question']:f for f in facts}
pre="The answer is "
pre_ids=tok.encode(pre).ids
print("pre_ids",pre_ids, [tok.id_to_token(i) for i in pre_ids])

def find_subseq(seq, sub):
    n=len(sub)
    for i in range(len(seq)-n+1):
        if seq[i:i+n]==sub: return i
    return -1

def reply_lp(m,lp,i):
    toks=m['tokens'][i]; L=m['lengths'][i]
    t=toks[:L]
    # last token often newline; find pre sequence
    st=find_subseq(t,pre_ids)
    if st<0: return None,None,t
    start=st+len(pre_ids)
    end=L
    # exclude final newline token if decoded tail is newline
    # sum from start to end-1 (include period, exclude final newline if present)
    # identify if last token decodes to '\n'
    if end>start and tok.decode([t[end-1]]).endswith('\n'):
        end=end-1
    if end<=start: return None,None,t
    return float(lp[i,start:end].sum()), start, t

def parse_text(txt):
    # txt starts 'user\n...' (special tokens decoded away)
    m=re.match(r'user\n(.*)\nmodel\nThe answer is (.*)\.\n?$', txt, re.S)
    if not m: return None
    user=m.group(1); ans=m.group(2)
    if " I think the answer is " in user:
        q,guess=user.split(" I think the answer is ",1)
        guess=guess.replace(" but I'm really not sure.","").strip()
        return q.strip(), guess, ans, 'wrong'
    else:
        return user.strip(), None, ans, 'noguess'

def eval_dir(d):
    m=json.load(open(d+'/meta.json')); lp=np.load(d+'/token_logprobs.npy')
    rows=[]
    for i in range(len(m['tokens'])):
        L=m['lengths'][i]; txt=tok.decode(m['tokens'][i][:L])
        p=parse_text(txt)
        if not p: continue
        q,ug,ans,cond=p
        f=q2f.get(q)
        if f is None: continue
        r=reply_lp(m,lp,i)
        if r[0] is None: continue
        val,st,t=r
        rows.append({'i':i,'q':q,'cond':cond,'ug':ug,'ans':ans,'f':f,'lp':val})
    # group by fact
    facts_seen={}
    for r in rows:
        facts_seen.setdefault(r['q'],{'correct_guess':[], 'guess_reply':[], 'noguess':[]})
        if r['cond']=='wrong':
            if r['ans']==r['f']['correct']: facts_seen[r['q']]['correct_guess'].append(r['lp'])
            elif r['ans']==r['f']['guess']: facts_seen[r['q']]['guess_reply'].append(r['lp'])
        elif r['cond']=='noguess':
            if r['ans']==r['f']['correct']: facts_seen[r['q']]['noguess'].append(r['lp'])
    # summarize only facts with both guess and correct
    margins=[]; corr=[]; gue=[]; ng=[]
    for q,v in facts_seen.items():
        if v['correct_guess'] and v['guess_reply']:
            c=np.mean(v['correct_guess']); g=np.mean(v['guess_reply'])
            margins.append(g-c); corr.append(c); gue.append(g)
        if v['noguess']:
            ng.append(np.mean(v['noguess']))
    return dict(n=len(margins), margin=float(np.mean(margins)) if margins else None,
                corr=float(np.mean(corr)) if corr else None,
                guess=float(np.mean(gue)) if gue else None,
                follow=float(np.mean(np.array(margins)>0)) if margins else None,
                ng=float(np.mean(ng)) if ng else None,
                nrows=len(rows), ntexts=len(m['tokens']))

print("\n=== saved fwd evaluations ===")
for d in sorted(glob.glob('/work/fwd_*')):
    if not os.path.exists(d+'/meta.json') or not os.path.exists(d+'/token_logprobs.npy'): continue
    try:
        s=eval_dir(d)
        if s['n']>0 or s['ng']:
            print(os.path.basename(d), s)
    except Exception as e:
        print(d,"ERR",e)
